package org.sleepwell.app;
import java.time.*;
import java.util.*;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;
/** Isolated SQLite and fake scheduler only. Never invokes any receiver or alarm runtime. */
public final class AlarmSkipStorageTest {
 @Test public void chosenDatePersistsAndBootZoneResolutionSkipsExactlyOneOccurrence()throws Exception{try(AlarmSkipFixture f=new AlarmSkipFixture()){long chosen=f.chosen();Alarm saved=AlarmSkips.skip(f.c,f.load(),chosen);String nonce=saved.skip.nonce;assertTrue(saved.enabled);assertEquals(Instant.parse("2026-10-26T06:30:00Z").toEpochMilli(),saved.next(f.now,f.zone));assertEquals(nonce,f.load().skip.nonce);f.zone=ZoneId.of("Asia/Riyadh");assertEquals(Instant.parse("2026-10-26T03:30:00Z").toEpochMilli(),f.load().next(f.now,f.zone));AlarmSkips.retry(f.c,f.load());assertEquals(nonce,f.load().skip.nonce);assertFalse(AlarmSkips.eligible(f.load(),saved.skip.at(f.zone),saved.skip.at(f.zone),0,f.zone));assertEquals(nonce,f.load().skip.nonce);Alarm restored=AlarmSkips.undo(f.c,f.load());assertNull(restored.skip);assertTrue(restored.enabled);assertEquals(Instant.parse("2026-10-23T03:30:00Z").toEpochMilli(),f.deadlines.get(f.deadlines.size()-1).longValue());}}
 @Test public void oneTimeIsOffAndExpiredUndoNeverRollsItIntoTomorrow()throws Exception{try(AlarmSkipFixture f=new AlarmSkipFixture()){try(Store store=f.open()){Alarm a=f.load();a.days.clear();store.save(a);}long chosen=f.chosen();Alarm saved=AlarmSkips.skip(f.c,f.load(),chosen);assertFalse(saved.enabled);assertEquals(0,f.deadlines.get(0).longValue());Alarm restored=AlarmSkips.undo(f.c,saved);assertTrue(restored.enabled);assertEquals(chosen,f.deadlines.get(1).longValue());saved=AlarmSkips.skip(f.c,restored,chosen);f.now=chosen;Alarm expected=saved;String before=f.load().json().toString();assertThrows(IllegalStateException.class,()->AlarmSkips.undo(f.c,expected));assertEquals(before,f.load().json().toString());assertFalse(f.load().enabled);}}
 @Test public void staleCallbacksAndEditorsCannotOverwriteNewSkipOwnership()throws Exception{try(AlarmSkipFixture f=new AlarmSkipFixture()){Alarm original=f.load();Alarm saved=AlarmSkips.skip(f.c,original,f.chosen());String first=saved.skip.nonce;assertThrows(IllegalStateException.class,()->AlarmSkips.skip(f.c,original,original.next(f.now,f.zone)));try(Store store=f.open()){Alarm nonschedule=Alarm.read(original.json());nonschedule.tone="pulse";AlarmSkips.prepareEdit(store,nonschedule,original,true);assertEquals(first,nonschedule.skip.nonce);store.save(nonschedule);Alarm changed=Alarm.read(original.json());changed.hour=8;assertThrows(IllegalStateException.class,()->AlarmSkips.prepareEdit(store,changed,original,true));}Alarm undone=AlarmSkips.undo(f.c,f.load());Alarm replacement=AlarmSkips.skip(f.c,undone,f.chosen());assertNotEquals(first,replacement.skip.nonce);assertThrows(IllegalStateException.class,()->AlarmSkips.undo(f.c,saved));assertEquals(replacement.skip.nonce,f.load().skip.nonce);try(Store store=f.open()){Alarm changed=Alarm.read(replacement.json());changed.hour=8;AlarmSkips.prepareEdit(store,changed,replacement,true);assertNull(changed.skip);store.save(changed);}assertNull(f.load().skip);}}
 @Test public void schedulingAndUndoFailurePersistWithoutClaimingDeliveryOrLosingIntent()throws Exception{try(AlarmSkipFixture f=new AlarmSkipFixture()){f.fail=true;Alarm saved=AlarmSkips.skip(f.c,f.load(),f.chosen());assertNotNull(saved.skip);assertFalse(f.load().scheduleError.isEmpty());Alarm retry=AlarmSkips.retry(f.c,f.load());assertEquals(saved.skip.nonce,retry.skip.nonce);assertFalse(retry.scheduleError.isEmpty());Alarm undone=AlarmSkips.undo(f.c,retry);assertNull(undone.skip);assertFalse(undone.scheduleError.isEmpty());assertTrue(undone.enabled);f.fail=false;Alarm repaired=AlarmSkips.retry(f.c,f.load());assertEquals("",repaired.scheduleError);assertNull(f.load().skip);}}
 @Test public void strictPortableCodecRejectsBadMetadataAndRestoreClearsAllSkipAuthority()throws Exception{try(AlarmSkipFixture f=new AlarmSkipFixture();Store store=f.open()){Alarm saved=AlarmSkips.skip(f.c,f.load(),f.chosen());JSONObject backup=store.backup();Backup.validate(backup);JSONObject bad=saved.json();bad.getJSONObject("skip").put("hour",6.5);assertTrue(Alarm.read(bad).skipInvalid);JSONObject invalidBackup=new JSONObject(backup.toString());invalidBackup.getJSONArray("alarms").put(0,bad);String before=BackupFingerprint.read(store);assertThrows(JSONException.class,()->Backup.restoreData(store,invalidBackup));assertEquals(before,BackupFingerprint.read(store));for(Object invalid:new Object[]{"6",6.5}){bad=saved.json();bad.getJSONObject("skip").put("hour",invalid);assertTrue(Alarm.read(bad).skipInvalid);}bad=saved.json();bad.getJSONObject("skip").put("surprise",true);assertTrue(Alarm.read(bad).skipInvalid);bad=saved.json();bad.put("hour",8);assertTrue(Alarm.read(bad).skipInvalid);Alarm nap=Alarm.read(saved.json());nap.nap=new NapPlan(UUID.randomUUID().toString(),"private",f.now,1000,1,20,false,NapPlan.Phase.CANCELLED,"");assertTrue(Alarm.read(nap.json()).skipInvalid);Backup.restoreData(store,backup);assertNull(store.alarm(1).skip);assertFalse(store.alarm(1).enabled);assertEquals("",store.alarm(1).scheduleError);assertEquals(1,f.schedules);}}
 @Test public void explicitToggleClearsSkipWhileDeletionAndChangedOccurrenceRejectStaleCommands()throws Exception{try(AlarmSkipFixture f=new AlarmSkipFixture();Store store=f.open()){Alarm saved=AlarmSkips.skip(f.c,f.load(),f.chosen());Alarm disabled=AlarmSkips.toggle(f.c,store,saved,false);assertFalse(disabled.enabled);assertNull(disabled.skip);assertThrows(IllegalStateException.class,()->AlarmSkips.undo(f.c,saved));Alarm enabled=AlarmSkips.toggle(f.c,store,disabled,true);f.now=enabled.next(f.now,f.zone)+1;assertThrows(IllegalStateException.class,()->AlarmSkips.skip(f.c,enabled,enabled.next(f.now-2,f.zone)));Alarm current=f.load();store.deleteAlarm(1);assertThrows(IllegalStateException.class,()->AlarmSkips.retry(f.c,current));assertNull(f.load());}}
 @Test public void replacementCannotInterleaveTheOwnershipReadAndIntentWrite()throws Exception{try(AlarmSkipFixture f=new AlarmSkipFixture()){
  java.util.concurrent.CountDownLatch read=new java.util.concurrent.CountDownLatch(1),release=new java.util.concurrent.CountDownLatch(1),attempt=new java.util.concurrent.CountDownLatch(1),replaced=new java.util.concurrent.CountDownLatch(1);java.util.concurrent.atomic.AtomicBoolean held=new java.util.concurrent.atomic.AtomicBoolean();java.util.concurrent.atomic.AtomicReference<Throwable> failure=new java.util.concurrent.atomic.AtomicReference<>();Alarm expected=f.load();long chosen=f.chosen();Records.Factory original=Records.factory;
  Records.factory=context->new Store(context,f.database){@Override public Alarm alarm(int id){Alarm value=super.alarm(id);if(Thread.currentThread().getName().equals("private-skip-change")&&held.compareAndSet(false,true)){read.countDown();try{assertTrue(release.await(5,java.util.concurrent.TimeUnit.SECONDS));}catch(InterruptedException interrupted){throw new IllegalStateException(interrupted);}}return value;}};
  Thread change=new Thread(()->{try{AlarmSkips.skip(f.c,expected,chosen);}catch(IllegalStateException raced){/* A completed replacement may reject the later scheduling/status step. */}catch(Throwable error){failure.set(error);}},"private-skip-change");Thread replacement=new Thread(()->{try(Store store=f.open()){attempt.countDown();android.database.sqlite.SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{Alarm imported=Alarm.read(expected.json());imported.enabled=false;AlarmSkips.clear(imported);store.save(imported);db.setTransactionSuccessful();}finally{db.endTransaction();}}catch(Throwable error){failure.set(error);}finally{replaced.countDown();}},"private-disabled-replacement");
  try{change.start();assertTrue(read.await(5,java.util.concurrent.TimeUnit.SECONDS));replacement.start();assertTrue(attempt.await(5,java.util.concurrent.TimeUnit.SECONDS));assertFalse("Replacement cannot pass the atomic saved ownership check/write",replaced.await(200,java.util.concurrent.TimeUnit.MILLISECONDS));}finally{release.countDown();change.join(5000);replacement.join(5000);Records.factory=original;}assertFalse(change.isAlive());assertFalse(replacement.isAlive());assertNull(failure.get());assertFalse(f.load().enabled);assertNull(f.load().skip);
 }}

 @Test public void newEditorDraftUsesDurableIntentAndKeepsSchedulingFailureReviewable()throws Exception{try(AlarmSkipFixture f=new AlarmSkipFixture();Store store=f.open()){Alarm draft=new Alarm(3);draft.enabled=true;Alarm original=Alarm.read(draft.json());f.fail=true;Alarm saved=AlarmSkips.edit(f.c,store,draft,original,false);assertTrue(store.alarm(3).enabled);assertFalse(saved.scheduleError.isEmpty());assertNull(saved.skip);f.fail=false;Alarm changed=Alarm.read(saved.json());changed.rampSeconds=120;Alarm retried=AlarmSkips.edit(f.c,store,changed,saved,true);assertEquals("",retried.scheduleError);assertEquals(120,store.alarm(3).rampSeconds);int before=f.schedules;assertThrows(AlarmSkips.Changed.class,()->AlarmSkips.edit(f.c,store,original,original,false));assertEquals(before,f.schedules);assertEquals(120,store.alarm(3).rampSeconds);}}

}
